/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var transposeStr2Enum = require( '@stdlib/blas/base/transpose-operation-str2enum' );
var layoutStr2Enum = require( '@stdlib/blas/base/layout-str2enum' );
var dscal = require( '@stdlib/blas/base/dscal' );
var dgemmsw = require( './../lib/dgemmsw.js' );


// FIXTURES //

var cntantb = require( './fixtures/column_major_nta_ntb.json' );
var ctatb = require( './fixtures/column_major_ta_tb.json' );
var rntantb = require( './fixtures/row_major_nta_ntb.json' );
var rtatb = require( './fixtures/row_major_ta_tb.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dgemmsw, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 14', function test( t ) {
	t.strictEqual( dgemmsw.length, 14, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided an invalid first argument', function test( t ) {
	var values;
	var data;
	var i;

	data = rntantb;

	values = [
		'foo',
		'bar',
		'beep',
		'boop'
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dgemmsw( value, data.transA, data.transB, data.M, data.N, data.K, data.alpha, new Float64Array( data.A ), data.lda, new Float64Array( data.B ), data.ldb, data.beta, new Float64Array( data.C ), data.ldc );
		};
	}
});

